// Record: one line, immutable, structural equality, with-expressions
public record OrderLine(string Sku, int Qty, decimal UnitPrice)
{
    public decimal Total => Qty * UnitPrice;
}

var a = new OrderLine("SKU-1", 2, 9.99m);
var b = a with { Qty = 3 };            // copy-modify, original untouched
Console.WriteLine(a == b);             // False — different Qty
Console.WriteLine(a == a with { });    // True  — same values, different instance

// Class: identity + mutable state
public class Customer
{
    public Guid Id { get; set; }       // identity — equality should use THIS
    public string Name { get; set; } = "";
    public List<Order> Orders { get; } = new();
}

var c1 = new Customer { Id = id, Name = "Nilay" };
var c2 = new Customer { Id = id, Name = "Nilay" };
Console.WriteLine(c1 == c2);           // False (reference equality) — correct for entities:
// They are two in-memory handles to the same logical customer only if Id matches —
// you compare Id explicitly (or implement IEquatable on Id) instead of field-by-field.

// readonly record struct: value semantics without heap allocation
public readonly record struct Money(decimal Amount, string Currency);
